    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n}\n\nenum ArticleStatus {\n  DRAFT\n  REVIEW\n  PUBLISHED\n  ARCHIVED\n}\n\nmodel User {\n  id           String     @id @default(uuid()) @db.VarChar(36)\n  email        String     @unique @db.VarChar(191)\n  username     String     @unique @db.VarChar(100)\n  passwordHash String     @db.VarChar(255)\n  firstName    String?    @db.VarChar(100)\n  lastName     String?    @db.VarChar(100)\n  status       UserStatus @default(ACTIVE)\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  roles     UserRole[]\n  sessions  AuthSession[]\n  articles  NewsArticle[]\n  auditLogs AuditLog[]\n\n  @@map(\"users\")\n}\n\nmodel Role {\n  id          String   @id @default(uuid()) @db.VarChar(36)\n  name        String   @unique @db.VarChar(100)\n  description String?  @db.VarChar(255)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  users       UserRole[]\n  permissions RolePermission[]\n\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String  @id @default(uuid()) @db.VarChar(36)\n  code        String  @unique @db.VarChar(150)\n  description String? @db.VarChar(255)\n\n  roles RolePermission[]\n\n  @@map(\"permissions\")\n}\n\nmodel UserRole {\n  userId String @db.VarChar(36)\n  roleId String @db.VarChar(36)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role Role @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@id([userId, roleId])\n  @@map(\"user_roles\")\n}\n\nmodel RolePermission {\n  roleId       String @db.VarChar(36)\n  permissionId String @db.VarChar(36)\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\nmodel AuthSession {\n  id               String    @id @default(uuid()) @db.VarChar(36)\n  userId           String    @db.VarChar(36)\n  refreshTokenHash String    @db.VarChar(255)\n  expiresAt        DateTime\n  revokedAt        DateTime?\n  createdAt        DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n  @@map(\"auth_sessions\")\n}\n\nmodel NewsCategory {\n  id          String   @id @default(uuid()) @db.VarChar(36)\n  name        String   @unique @db.VarChar(150)\n  slug        String   @unique @db.VarChar(191)\n  description String?  @db.Text\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  articles NewsArticle[]\n\n  @@map(\"news_categories\")\n}\n\nmodel NewsArticle {\n  id          String        @id @default(uuid()) @db.VarChar(36)\n  title       String        @db.VarChar(255)\n  slug        String        @unique @db.VarChar(191)\n  summary     String?       @db.Text\n  content     String        @db.LongText\n  imageUrl    String?       @db.VarChar(2048)\n  status      ArticleStatus @default(DRAFT)\n  authorId    String        @db.VarChar(36)\n  categoryId  String        @db.VarChar(36)\n  publishedAt DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  author   User         @relation(fields: [authorId], references: [id])\n  category NewsCategory @relation(fields: [categoryId], references: [id])\n\n  @@index([status, publishedAt])\n  @@index([categoryId])\n  @@index([authorId])\n  @@map(\"news_articles\")\n}\n\nmodel AuditLog {\n  id         String   @id @default(uuid()) @db.VarChar(36)\n  userId     String?  @db.VarChar(36)\n  action     String   @db.VarChar(150)\n  entityType String   @db.VarChar(100)\n  entityId   String?  @db.VarChar(36)\n  details    Json?\n  ipAddress  String?  @db.VarChar(45)\n  createdAt  DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([entityType, entityId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n",
